//from https://www.shadertoy.com/view/XX3yRn
float ibuki(vec4 v)
{
    const uvec4 mult = 
        uvec4(0xae3cc725, 0x9fe72885, 0xae36bfb5, 0x82c1fcad);

    uvec4 u = uvec4(v);
    u *= mult;
    u ^= u.wxyz ^ u >> 13; 
    u *= mult;

    uint r = u.x + u.y + u.z + u.w;
    r ^= r >> 11;
    r = (r * r) ^ r;

    return float(r) * 2.3283064365386962890625e-10;
}
float sdCircleWave( in vec2 p, in float tb, in float ra )
{
    tb = 3.1415927*5.0/6.0*max(tb,0.0001);
    vec2 co = ra*vec2(sin(tb),cos(tb));
    p.x = abs(mod(p.x,co.x*4.0)-co.x*2.0);
    vec2  p1 = p;
    vec2  p2 = vec2(abs(p.x-2.0*co.x),-p.y+2.0*co.y);
    float d1 = ((co.y*p1.x>co.x*p1.y) ? length(p1-co) : abs(length(p1)-ra));
    float d2 = ((co.y*p2.x>co.x*p2.y) ? length(p2-co) : abs(length(p2)-ra));
    return min(d1, d2); 
}
